// Helpers shared by the repo scripts. Node built-ins only.
import { spawnSync } from "node:child_process"
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs"
import { dirname, join, relative, resolve } from "node:path"
import { fileURLToPath } from "node:url"

export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..")
export const PLUGINS_DIR = join(ROOT, "plugins")
export const PLUGIN_PREFIX = "medusa-plugin-"
export const SCOPE = "@bitshaft"

/** Marker every generated file starts with (kit copies, vendored files). */
export const GENERATED_MARKER = "GENERATED by medusa-integrations"

/** Every folder in plugins/, sorted. */
export function listPlugins() {
  if (!existsSync(PLUGINS_DIR)) {
    return []
  }
  return readdirSync(PLUGINS_DIR)
    .filter((name) => statSync(join(PLUGINS_DIR, name)).isDirectory())
    .sort()
    .map((folder) => ({
      folder,
      dir: join(PLUGINS_DIR, folder),
      namespace: folder.startsWith(PLUGIN_PREFIX) ? folder.slice(PLUGIN_PREFIX.length) : folder,
    }))
}

export function readJson(file) {
  return JSON.parse(readFileSync(file, "utf8"))
}

/** All files under `dir` as forward-slash paths relative to `dir`. */
export function walk(dir, { skip = [] } = {}) {
  const out = []
  const visit = (current) => {
    if (!existsSync(current)) {
      return
    }
    for (const name of readdirSync(current)) {
      if (skip.includes(name)) {
        continue
      }
      const full = join(current, name)
      if (statSync(full).isDirectory()) {
        visit(full)
      } else {
        out.push(relative(dir, full).split("\\").join("/"))
      }
    }
  }
  visit(dir)
  return out.sort()
}

/** Comment syntax for the generated header, or null when the format has none (JSON). */
export function headerFor(file, text) {
  if (/\.(ts|tsx|js|mjs|cjs|mts|cts)$/.test(file)) {
    return `// ${GENERATED_MARKER}: ${text}\n`
  }
  if (/\.css$/.test(file)) {
    return `/* ${GENERATED_MARKER}: ${text} */\n`
  }
  if (/\.md$/.test(file)) {
    return `<!-- ${GENERATED_MARKER}: ${text} -->\n`
  }
  return null
}

/** Runs a command with inherited output; returns the exit code. */
export function run(command, args, options = {}) {
  // On Windows npm/npx are .cmd shims and need a shell; pass one quoted command
  // line instead of an args array (which Node deprecates together with shell: true).
  const useShell = options.shell ?? process.platform === "win32"
  const result = useShell
    ? spawnSync([command, ...args].map(quoteArg).join(" "), { stdio: "inherit", ...options, shell: true })
    : spawnSync(command, args, { stdio: "inherit", ...options, shell: false })
  if (result.error) {
    console.error(result.error.message)
    return 1
  }
  return result.status ?? 1
}

function quoteArg(arg) {
  return /^[\w@%+=:,./\\-]+$/.test(arg) ? arg : `"${String(arg).replace(/"/g, '\\"')}"`
}

export function toLf(text) {
  return text.replace(/\r\n/g, "\n")
}
